"""specs_s200048.py - Sonnet-w2 family Z2 (generated by mkfamZ2.py): the engine object (vtable slot 0x1a8 stub, table pointer at +0x9b with a slot 0x34 stub) and the owned member (slot 0 stub or null)
record the SEH chain and the object's vtable word; fake outer SEH records 0-2; fs:[0] compared."""
from pilot import S
from recruits_util import rnd, obj, clear_hooks, pystub, seh_record, seh_chain


def _side(c, o):
    sr = seh_record(c, 2)

    def side(emu, k):
        emu.calllog.append(('vt', emu.r32(o)))
        sr(emu, k)
    return side


def _mk(off):
    def gen(c):
        clear_hooks(c)
        seh_chain(c, c.rng.choice([0, 1, 2]))
        r = c.rng
        o = rnd(c, 0xb00)
        eng = obj(c, 0x1b00, {0x1a8: pystub(c, 1, ret=r.getrandbits(32), this=True, side=_side(c, o))}, nslots=0x70)
        tb = obj(c, 0x40, {0x34: pystub(c, 1, ret=r.getrandbits(32), this=True, side=_side(c, o))}, nslots=0x20)
        c.emu.w32(eng + 0x9b, tb)
        c.emu.w32(0x70039c, eng)
        mem = obj(c, 0x20, {0: pystub(c, 1, ret=r.getrandbits(32), this=True, side=_side(c, o))}, nslots=2) if r.random() < 0.75 else 0
        c.emu.w32(o + off, mem)
        return [o]
    return gen


S(0x566c90, 'GUESS famZ2 0x566c90', 'thiscall', None, ret='eax', gen=_mk(0x180), note='batch200048')
S(0x5cd450, 'GUESS famZ2 0x5cd450', 'thiscall', None, ret='eax', gen=_mk(0xa50), note='batch200048')
